const req = $('Webhook').first().json.body ?? {};
const phone = String(req.phone ?? '').trim();
const res = $json ?? {};

// THREE outcomes, not two. A bad API key, a wrong formname or an unknown field
// all make Cratio return an error — and if that reads as "not found", a
// misconfigured lookup is indistinguishable from a lead that genuinely went
// missing, and the dashboard raises a critical alert about the wrong thing.
const err = res.error ?? res.Error ?? (Array.isArray(res) ? res[0]?.error : null);
if (err) {
  return [{ json: { result: 'LEAD_ERROR', checked: phone, detail: String(err).slice(0, 200) } }];
}

// {"success":[{"totalrows":N,"data":[...]}]} on a hit.
const rows = Number(res?.success?.[0]?.totalrows ?? 0);
const found = rows > 0 || JSON.stringify(res).includes(phone);

// A token, never the phone number itself: a not-found reply that echoed the
// value back would match the search string and read as a hit.
return [{ json: {
  result: found ? 'LEAD_FOUND' : 'LEAD_MISSING',
  checked: phone,
  rows,
  // Enough of the raw reply to diagnose a wrong formname without a second run.
  detail: found ? undefined : JSON.stringify(res).slice(0, 200),
} }];
